package com.vincenthuto.hemomancy.common.block;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.HashSet;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.*;

/** The Iron Brazier's standing, wall-mounted and hanging models, generated by tools/model_export/iron_brazier.py. */
final class IronBrazierMountModelResourceTest {
	private static final Path ASSETS = Path.of("src/main/resources/assets/hemomancy");
	private static final String[] FACES = {"floor", "wall", "ceiling"};
	private static final String[] FACINGS = {"north", "east", "south", "west"};

	@Test
	void everyMountAndFacingHasItsBodyInTheBlockstate() throws IOException {
		JsonObject blockstate = read(ASSETS.resolve("blockstates/iron_brazier.json"));
		Set<String> bodies = new HashSet<>();
		for (JsonElement element : blockstate.getAsJsonArray("multipart")) {
			JsonObject part = element.getAsJsonObject();
			JsonObject when = part.getAsJsonObject("when");
			assertTrue(when.has("face") && when.has("facing"), "every part keys on the mount and facing: " + when);
			String model = part.getAsJsonObject("apply").get("model").getAsString();
			assertTrue(Files.exists(ASSETS.resolve("models/" + model.replace("hemomancy:", "") + ".json")),
					"the blockstate names a model that exists: " + model);
			if (!when.has("ritual_phase")) bodies.add(when.get("face").getAsString() + "/" + when.get("facing").getAsString());
		}
		for (String face : FACES) {
			for (String facing : FACINGS) {
				assertTrue(bodies.contains(face + "/" + facing), "no body for " + face + " facing " + facing);
			}
		}
	}

	@Test
	void sconcesAndHangingBraziersCarryTheirMountsInsteadOfAStem() throws IOException {
		Set<String> wall = names("iron_brazier_wall");
		Set<String> hanging = names("iron_brazier_hanging");
		for (Set<String> body : java.util.List.of(wall, hanging)) {
			assertFalse(body.contains("dais") || body.contains("stem_core"), "a mounted brazier has no dais or stem");
			assertTrue(body.contains("bowl_wall") && body.contains("talon_tip") && body.contains("spout_lip"),
					"the same bowl, talons and spout as the standing brazier");
		}
		assertTrue(wall.contains("wall_plate") && wall.contains("bracket_arm"), "a sconce hangs on a plate and arm");
		assertTrue(hanging.contains("ceiling_plate") && hanging.contains("chain_link"), "a hanging brazier hangs on chains");
		for (String model : new String[] {"iron_brazier_wall_lit", "iron_brazier_wall_sanguine", "iron_brazier_hanging_lit",
				"iron_brazier_hanging_sanguine"}) {
			assertTrue(Files.exists(ASSETS.resolve("models/block/" + model + ".json")), model);
		}
	}

	private static Set<String> names(String model) throws IOException {
		Set<String> names = new HashSet<>();
		for (JsonElement element : read(ASSETS.resolve("models/block/" + model + ".json")).getAsJsonArray("elements")) {
			names.add(element.getAsJsonObject().get("name").getAsString());
		}
		return names;
	}

	private static JsonObject read(Path path) throws IOException {
		return JsonParser.parseString(Files.readString(path)).getAsJsonObject();
	}
}
